package com.retailpos.server.common;

import java.security.SecureRandom;
import java.util.UUID;

/** Time-ordered UUIDs (RFC 9562 v7). Used for all primary keys; generated by the app, not the DB. */
public final class UuidV7 {

    private static final SecureRandom RANDOM = new SecureRandom();

    private UuidV7() {}

    public static UUID next() {
        return next(System.currentTimeMillis());
    }

    static UUID next(long epochMillis) {
        byte[] rand = new byte[10];
        RANDOM.nextBytes(rand);
        long msb = (epochMillis & 0xFFFFFFFFFFFFL) << 16;            // 48-bit unix ms
        msb |= 0x7000L;                                               // version 7
        msb |= ((rand[0] & 0x0FL) << 8) | (rand[1] & 0xFFL);          // 12 random bits
        long lsb = 0x8000000000000000L;                               // variant 10
        lsb |= (rand[2] & 0x3FL) << 56;
        for (int i = 3; i < 10; i++) {
            lsb |= (rand[i] & 0xFFL) << (8 * (9 - i));
        }
        return new UUID(msb, lsb);
    }
}
